arguments.command:
Set-Content -Path "count_lines.py" -Value 'import sys
import os

def count_lines():
    if len(sys.argv) != 2:
        print("Usage: python count_lines.py <filename>")
        return

    filename = sys.argv[1]
    if not os.path.exists(filename):
        print(f"Error: File "{filename}" not found.")
        return

    try:
        with open(filename, "r", encoding="utf-8") as f:
            count = sum(1 for _ in f)
            print(f"Total lines: {count}")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    count_lines()'

$extensions = @{".txt"="Text Files"; ".pdf"="Documents"; ".jpg"="Images"; ".mp3"="Audio"}
Get-ChildItem -Path ".\Inbox" -File | ForEach-Object {
    $ext = $_.Extension.ToLower()
    if ($extensions.ContainsKey($ext)) {
        $folder = $extensions[$ext]
        if (-not (Test-Path $folder)) { New-Item -ItemType Directory -Name $folder }
        Move-Item -Path $_.FullName -Destination $folder
    }
}
